struct reg_entry { const char *name; void *impl; };
static struct reg_entry reg[64];
static size_t reg_n;
void registry_register(const char *name, void *impl) {
    if (reg_n == 64) abort();             /* full: fail fast */
    reg[reg_n++] = (struct reg_entry){ name, impl };
}
void *registry_lookup(const char *name) {
    for (size_t i = 0; i < reg_n; i++)
        if (strcmp(reg[i].name, name) == 0) return reg[i].impl;
    return NULL;
}

